//! Fixed-order Gauss-Legendre quadrature (gh:#1340), ported from GSL 2.8
//! `integration/glfixed.c` (`gsl_integration_glfixed_table_alloc` lines
//! 181-245, `gsl_integration_glfixed` 280-319, `gsl_integration_glfixed_point`
//! 327-366, `gauss_legendre_tbl` 379-483), commit `cf180cd7`, read
//! 2026-11-13. Copyright (C) 2008 Brian Gough (Konstantin Holoborodko,
//! Rhys Ulerich), GPL-3.0-or-later. Research, education and V&V only.
//!
//! A table for `n` points is either one of GSL's 27 precomputed sizes
//! ([`super::glfixed_tables`], copied from the C file) or generated by
//! Newton's method on the Legendre polynomial (`gauss_legendre_tbl`, with
//! GSL's `eps = 1e-10`), exactly as upstream.
//!
//! # Differences from upstream
//!
//! - The table owns `Vec`s for both kinds (upstream points at static data for
//!   the precomputed sizes), so there is no `free`.
//! - `n == 0` is [`PetirError::Invalid`] (upstream `malloc(0)`s a table that
//!   integrates to zero); `n > i32::MAX` is `Invalid` as upstream's `EINVAL`.
//! - Every array access is a checked `get` (`no_panic_gate`).
//! - The initial guess uses PETIR's `cos`; upstream uses the platform's.

#[allow(unused_imports)]
use crate::real::Real;
use crate::{PetirError, Result};
use alloc::vec;
use alloc::vec::Vec;

use super::glfixed_tables::{precomputed, LTBL};

/// `gsl_integration_glfixed_table`: `n` points, `(n + 1) / 2` stored
/// non-negative abscissae and weights (`x[0] == 0` for odd `n`).
#[derive(Debug, Clone, PartialEq)]
pub struct GlFixedTable {
    n: usize,
    x: Vec<f64>,
    w: Vec<f64>,
    precomputed: bool,
}

impl GlFixedTable {
    /// The number of points.
    pub fn n(&self) -> usize {
        self.n
    }

    /// Whether the table came from GSL's precomputed list.
    pub fn is_precomputed(&self) -> bool {
        self.precomputed
    }

    /// The stored abscissae (`(n + 1) / 2` of them), as GSL lays them out.
    pub fn abscissae(&self) -> &[f64] {
        &self.x
    }

    /// The stored weights.
    pub fn weights(&self) -> &[f64] {
        &self.w
    }
}

fn rd(v: &[f64], i: usize) -> f64 {
    v.get(i).copied().unwrap_or(0.0)
}

fn wr(v: &mut [f64], i: usize, x: f64) {
    if let Some(s) = v.get_mut(i) {
        *s = x;
    }
}

/// `gsl_integration_glfixed_table_alloc`.
///
/// # Errors
///
/// [`PetirError::Invalid`] for `n == 0` or `n > i32::MAX`.
///
/// # Example
///
/// ```
/// use petir::integration::{glfixed, glfixed_table_alloc};
/// let t = glfixed_table_alloc(5).unwrap();
/// let v = glfixed(|x: f64| x.powi(9), 0.0, 1.0, &t); // exact to degree 9
/// assert!((v - 0.1).abs() < 1e-15);
/// ```
pub fn glfixed_table_alloc(n: usize) -> Result<GlFixedTable> {
    if n == 0 || n > i32::MAX as usize {
        return Err(PetirError::Invalid);
    }
    if let Some((x, w)) = precomputed(n) {
        return Ok(GlFixedTable {
            n,
            x: x.to_vec(),
            w: w.to_vec(),
            precomputed: true,
        });
    }
    let m = (n + 1) >> 1;
    let mut x = vec![0.0_f64; m];
    let mut w = vec![0.0_f64; m];
    gauss_legendre_tbl(n, &mut x, &mut w, 1e-10);
    Ok(GlFixedTable {
        n,
        x,
        w,
        precomputed: false,
    })
}

/// `gsl_integration_glfixed`: the `n`-point Gauss-Legendre rule on `[a, b]`.
pub fn glfixed<F>(f: F, a: f64, b: f64, t: &GlFixedTable) -> f64
where
    F: Fn(f64) -> f64,
{
    let n = t.n;
    let m = (n + 1) >> 1;
    let aa = 0.5 * (b - a);
    let bb = 0.5 * (b + a);
    let mut s;

    if n & 1 == 1 {
        // n odd
        s = rd(&t.w, 0) * f(bb);
        for i in 1..m {
            let ax = aa * rd(&t.x, i);
            s += rd(&t.w, i) * (f(bb + ax) + f(bb - ax));
        }
    } else {
        s = 0.0;
        for i in 0..m {
            let ax = aa * rd(&t.x, i);
            s += rd(&t.w, i) * (f(bb + ax) + f(bb - ax));
        }
    }
    aa * s
}

/// `gsl_integration_glfixed_point`: the `i`-th abscissa and weight on
/// `[a, b]`, in increasing order of abscissa.
///
/// # Errors
///
/// [`PetirError::Invalid`] if `i >= n` (`GSL_EINVAL`).
pub fn glfixed_point(a: f64, b: f64, i: usize, t: &GlFixedTable) -> Result<(f64, f64)> {
    let aa = (b - a) / 2.0;
    let bb = (a + b) / 2.0;
    if i >= t.n {
        return Err(PetirError::Invalid);
    }
    if t.n & 1 == 1 {
        let k = (i as i64) - (t.n as i64) / 2;
        let s: f64 = if k < 0 { -1.0 } else { 1.0 };
        let idx = k.unsigned_abs() as usize;
        let xi = bb + s * aa * rd(&t.x, idx);
        let wi = aa * rd(&t.w, idx);
        Ok((xi, wi))
    } else if i < t.n / 2 {
        let j = (t.n / 2) - 1 - i;
        Ok((bb - aa * rd(&t.x, j), aa * rd(&t.w, j)))
    } else {
        let j = i - t.n / 2;
        Ok((bb + aa * rd(&t.x, j), aa * rd(&t.w, j)))
    }
}

/// `gauss_legendre_tbl` (glfixed.c lines 379-483): Newton iteration for the
/// roots of the Legendre polynomial of degree `n` and their weights.
#[allow(clippy::excessive_precision)]
fn gauss_legendre_tbl(n: usize, x: &mut [f64], w: &mut [f64], eps: f64) {
    let nd = n as f64;
    let m = (n + 1) >> 1;
    let t0 = 1.0 - (1.0 - 1.0 / nd) / (8.0 * nd * nd);
    let t1 = 1.0 / (4.0 * nd + 2.0);

    for i in 1..=m {
        // Initial guess.
        let pi_to_many_places = 3.141_592_653_589_793_238_462_643_383_279_502_884_197_169_399_375_1;
        let mut x0 = Real::cos(pi_to_many_places * (((i << 2) - 1) as f64) * t1) * t0;

        let mut j = 0;
        let mut dx;
        let mut dw;
        let mut w0 = 0.0_f64;
        let mut x1;
        let mut w1;

        loop {
            // Legendre polynomial value at x0.
            let mut p_1 = 1.0_f64;
            let mut p0 = x0;
            if n < 1024 {
                for k in 2..=n {
                    let p_2 = p_1;
                    p_1 = p0;
                    let t2 = x0 * p_1;
                    p0 = t2 + rd(&LTBL, k) * (t2 - p_2);
                }
            } else {
                for k in 2..1024 {
                    let p_2 = p_1;
                    p_1 = p0;
                    let t2 = x0 * p_1;
                    p0 = t2 + rd(&LTBL, k) * (t2 - p_2);
                }
                for k in 1024..=n {
                    let p_2 = p_1;
                    p_1 = p0;
                    let t2 = x0 * p_1;
                    let t3 = ((k - 1) as f64) / (k as f64);
                    p0 = t2 + t3 * (t2 - p_2);
                }
            }

            // Derivative at x0.
            let dpdx = ((x0 * p0 - p_1) * nd) / (x0 * x0 - 1.0);
            // Newton step.
            x1 = x0 - p0 / dpdx;
            // Weight.
            w1 = 2.0 / ((1.0 - x1 * x1) * dpdx * dpdx);
            if j == 0 {
                w0 = 2.0 / ((1.0 - x0 * x0) * dpdx * dpdx);
            }
            dx = x0 - x1;
            dw = w0 - w1;
            x0 = x1;
            w0 = w1;
            j += 1;
            if !((dx.abs() > eps || dw.abs() > eps) && j < 100) {
                break;
            }
        }

        wr(x, (m - 1) - (i - 1), x1);
        wr(w, (m - 1) - (i - 1), w1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_to_degree_and_points_ordered() {
        for n in [2usize, 5, 21, 33, 1025] {
            let t = glfixed_table_alloc(n).unwrap();
            assert_eq!(t.is_precomputed(), precomputed(n).is_some());
            let v = glfixed(|x: f64| x * x, 0.0, 3.0, &t);
            assert!((v - 9.0).abs() < 1e-9, "n={n}: {v}");
            let mut last = f64::NEG_INFINITY;
            let mut wsum = 0.0;
            for i in 0..n {
                let (xi, wi) = glfixed_point(0.0, 3.0, i, &t).unwrap();
                assert!(xi > last);
                last = xi;
                wsum += wi;
            }
            assert!((wsum - 3.0).abs() < 1e-9);
            assert_eq!(glfixed_point(0.0, 1.0, n, &t), Err(PetirError::Invalid));
        }
        assert!(glfixed_table_alloc(0).is_err());
        assert_eq!(glfixed_table_alloc(7).unwrap().abscissae().len(), 4);
        assert_eq!(glfixed_table_alloc(7).unwrap().weights().len(), 4);
        assert_eq!(glfixed_table_alloc(7).unwrap().n(), 7);
    }

    #[test]
    fn ltbl_is_one_minus_reciprocal() {
        // The C comment says ltbl[k] = 1.0 - 1.0/(double)k.
        let mut off = 0;
        for k in 2..1024usize {
            if rd(&LTBL, k).to_bits() != (1.0 - 1.0 / (k as f64)).to_bits() {
                off += 1;
            }
        }
        // Measured; see verification_and_validation/integration_family_gh1340.md.
        assert_eq!(off, 0, "entries of LTBL that differ from 1 - 1/k");
    }
}
